style.css:
@-moz-document domain("roblox.com") {
/* Add the background image */
  body::before {
    content: '';
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: url('https://i.imgur.com/6SOHdua.png') no-repeat center center fixed;
    background-size: cover;
    z-index: -1; /* Places the image in the background */
    opacity: 1; /* Adjust this if transparency is needed */
  }

  /* Remove default Roblox dark theme background */
  body {
    background: none !important;
  }
}

@-moz-document domain("roblox.com") {
body::before {
    content: '';
    display: block;
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: url('https://i.imgur.com/6SOHdua.png') no-repeat center center fixed;
    background-size: cover;
    z-index: -1; /* Keeps the image in the background */
    opacity: 1; /* Adjust transparency if needed */
  }

  /* Optional: Hide any Roblox-specific background */
  body {
    background: none !important;
  }
}
